TLM.f("Sancti/10-08",{"officium":"S. Birgittæ Viduæ","rule":["vide C7a;","Gloria"],"fallback":"Commune/C7a","from":{"Introitus":"Commune/C7a","Graduale":"Commune/C7a","GradualeP":"Commune/C7a","Tractus":"Commune/C7a","Evangelium":"Commune/C7a","Offertorium":"Commune/C7a","Communio":"Commune/C7a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:75; 118:120"},{"k":"text","la":"Cognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cognóvi, Dómine, quia ǽquitas judícia tua, et in veritáte tua humiliásti me: confíge timóre tuo carnes meas, a mandátis tuis tímui. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Dómine, Deus noster, qui beátæ Birgíttæ per Fílium tuum unigénitum secreta cœléstia revelásti: ipsíus pia intercessióne da nobis, fámulis tuis; in revelatióne sempitérna glóriæ tuæ gaudére lætántes."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"1 Tim 5:3-10"},{"k":"text","la":"Caríssime: Víduas honóra, quæ vere víduæ sunt. Si qua autem vídua fílios aut nepótes habet, discat primum domum suam régere, et mútuam vicem réddere paréntibus: hoc enim accéptum est coram Deo. Quæ autem vere vídua est et desoláta, speret in Deum, et instet obsecratiónibus et oratiónibus nocte ac die. Nam quæ in delíciis est, vivens mórtua est. Et hoc prǽcipe, ut irreprehensíbiles sint. Si quis autem suórum, et máxime domesticórum curam non habet, fidem negávit, et est infidéli detérior. Vídua eligátur non minus sexagínta annórum, quæ fúerit uníus viri uxor, in opéribus bonis testimónium habens, si fílios educávit, si hospítio recépit, si sanctórum pedes lavit, si tribulatiónem patiéntibus subministrávit, si omne opus bonum subsecúta est."}],"Graduale":[{"k":"ref","la":"Ps 44:3; 44:5"},{"k":"text","la":"Diffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 44:3; 44:5"},{"k":"text","la":"Diffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et de ducet te mirabíliter déxtera tua.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe coronam, quam tibi Dóminus præparávit in ætérnum."},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, oleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera."}],"Offertorium":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi."}],"Secreta":[{"k":"text","la":"Accépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis."}],"Postcommunio":[{"k":"text","la":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"01c32e898bef2347":{"t":"Ps 118, 75 i 120, Ps 118, 1\n(Ps 118, 75 i 120) Znam, Gospodine, da je pravedan sud tvoj i da si me pravedno ponizio. Prožmi svojim strahom moje tijelo da se bojim tvoga suda. (Ps 118, 1) Blago onima koji idu neokaljanim putem, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 75 i 120) Znam, Gospodine, da je pravedan sud tvoj i da si me pravedno ponizio. Prožmi svojim strahom moje tijelo da se bojim tvoga suda.","kn":"(Ps. 113, 120). Znam, Gospodine, da pravo sudiš i da si me u vjernosti svojoj tako ponizio; prožmi strahom svojim tijelo moje, da se bojim suda tvoga. (Ps. 118, 1) Blago -onima, koji su čista života, koji žive po zakonu Gospodnjem! Slava Ocu . . ■ Zna-m . . .","knRef":"Kniewald 1942, str. 830–831 (snimka 416) (OCR)"},"aca314063acebcf3":{"t":"<i>Pomolimo se</i>.\nGospodine Bože, koji si blaženoj Brigiti objavio po svome Sinu nebeske tajne, daj nama svojim slugama po njezinu pobožnom zagovoru da se veselo radujemo pri objavi tvoje vječne slave.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Gospodine, Bože naš, koji si blaženoj Birgiti po svom Jedlnorođenom Sinu objavio nebeske tajne, podaj nama, slugama svojim, njezinim pobožnim zagovorom, da se radujemo u veselju objavljenja vječne slave Tvoje, po istom G. n.","knRef":"Kniewald 1942, str. 730–731 (snimka 366) (OCR)"},"62fcd31ded6c77ac":{"t":"1 Tim 5, 3-10\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi, poštuj udovice koje su prave udovice. Koja udovica ima djece ili unučadi, neka najprije nauči upravljati svojim domom i dobro uzvraćati roditeljima, jer je to Bogu milo. Koja je prava udovica i osamljena, neka se pouzda u Boga i ustraje u prošnjama i molitvama noć i dan. A ona koja je odana užitcima živa je umrla. I naglasi im da budu besprijekorne. Koji se ne brine za svoje, navlastito za ukućane, taj je zanijekao vjeru, gori je od nevjernika. Među izabrane udovice neka se uvrsti ne mlađa od šezdeset godina, koja se udala samo jedanput, koju preporučuju dobra djela: ako je djecu čestito odgojila, bila gostoljubiva, prala noge svetima, pomagala patnicima i vršila dobročinstva svake vrsti.","kn":"Čitanje poslanice bi. Pavla apostola Timoteju (1, udovice. Ako li koja udovica ima djecu ili unučad, neka se nauče najprije svoj dom poštivati, i zajam vračati roditeljima; jer je ovo ugodno pred Bogom. Koja je prava udovica i osamljena, uzda se u Boga, i ustraje u molitvama i u prošnjama noć i dan. A koja živi u nasladama, živa je umrla. I ovo zapovjedaj, da budu bez mane. A ako li se tko za svoje, a osobito za domaće ne brine, odrekao se vjere i gori je od nevjernika. A udovica neka se ne iizabere* mlađa od šezdeset godina, koja je bila jednomu mužu ženai i koja ima svjedočanstvo u dobrjm dielima; ako je djecu odgojila, akO' je gostoljubiva bila, ako je svetima noge oprala, ako je nevoljnima /pomogla, ako se posvetila svakom dabrom djelu.","knRef":"Kniewald 1942, str. 564–565 (snimka 283) (OCR)"},"4ff1a0907202750a":{"t":"Ps 44, 3 i 5\nMilina se razlila na tvojim usnama, stoga te je Bog blagoslovio u vijeke. Zbog vjernosti, blagosti i pravednosti divno će te voditi tvoja desnica.\n\nPs 44, 5\n<i>Aleluja</i>, <i>aleluja</i>.\nU svojoj veličanstvenoj ljepoti sretno pođi, napreduj i kraljuj. <i>Aleluja</i>.","kn":"(Ps. 44, 3, 4). Tvojim se usnama razlio blagoslov, jer te Bog blagoslovio blagoslovom t vječnim. Poradi istine i pravde i blagosti vodit će te divno desnica tvoja.\n\nAleluja; aleluja. (Ps. 44, 5.) U svojoj veličanstvenoj ljepoti .sretno pođi, pohitaj prema pobjedi i kraljuj! Aleluja.","knRef":"Kniewald 1942, str. 532–533 (snimka 267) (OCR)"},"599856a3c73c1a30":{"t":"Mt 13, 44-52\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao sakriveno blago u njivi koje, kad čovjek nađe, sakrije, te veseo ode i proda sve što ima i kupi onu njivu. Kraljevstvo je nebesko još kao trgovac koji traži prave bisere. I kad nađe jedan dragocjeni biser, ode i proda sve što ima i kupi ga. Nadalje kraljevstvo je nebesko kao mreža koja se baca u more i hvata sve vrsti riba. Kad se napuni, izvuku je i sjednu uz kraj, izaberu dobre ribe u posude a izbace zle. Tako će biti na svršetku svijeta. Izići će anđeli i odijeliti će opake od pravednih i bacit će ih u ognjenu peć. Ondje će biti plač i škripanje zubi. Jeste li razumjeli sve ovo? Odgovore mu: Jesmo. Tada im reče: Zato je svaki književnik koji je poučen u tajnama kraljevstva nebeskoga kao domaćin koji od svoga blaga iznosi novo i staro.","kn":"t Slijedi sv. evanđelje po Matejn (13, 44-52). U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao sakriveno blago u njivi, koje, kad čovjek nađe, sakrije, te veseo ode i proda sve, što ima i kupi onu njivu. Kraljevstvo je nebesko još kao trgovac, koji traži pravo biserje. I kad nađe jedan dragocjeni biser, ode i proda sve, što ima i kupi ga. Nadalje kraljevstvo^ je nebesko kao mreža, koja se baca u more i hvata sve vrsti riba. Kad se napuni, izvuku je i sjednu uz kraj, izaberu dobre ribe u posude, a izbace zle. Tako će biti na svršetku svijeta: Izići će anđeli i odijelit će opake od pravednih i bacit će ih u ognjenu peć; ondje će biti plač i škripa zubi. Jeste li razumjeli sve ovo? Odgovore mu: Jesmo. Tada im reče: Zato je svaki književnik,, koji je poučen u tajnaman kraljevstva nebeskoga, kao domaćin, koji od svoga blaga iznosi novo i staro.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"f13ce0f2fb02da20":{"t":"Ps 44, 3\nRazlita je milina na tvojim usnama, zbog toga te Bog blagoslovi u vijeke, i u vijeke vjekova.","kn":"(Ps. 44, 3). Razlita je milost na usnama tvojim, toga radi blagoslovi te Bog u vijeke, i u vijeke vijeka.","knRef":"Kniewald 1942, str. 500–501 (snimka 251) (OCR)"},"135c5bf58bce477d":{"t":"Pogledaj, Gospodine, na darove svoga naroda, i daj mu osjetiti da mu koristi za spasenje ova žrtvena svečanost koju obavlja s pobožnom odanošću na čast tvojih svetih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"e85443c9b9dcac8f":{"t":"Ps 44, 8\nLjubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje.","kn":"(Ps. 44, 8). Ljubiš pravdu i mrziš nepravdu, zato te pomazao Gospodin Bog tvoj uljem radosti izabravši te od svih drugarica tvojih.","knRef":"Kniewald 1942, str. 834–835 (snimka 418) (OCR)"},"dfce8e9a1c23b4e0":{"t":"<i>Pomolimo se</i>.\nNasitio si, Gospodine, svoju obitelj svetim darovima, molimo da nas uvijek krijepiš na zagovor one čiju svečanost slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pošto si nahranio svoju obitelj presvetim darovima, da nas uvijek krijepiš zagovorom one, koje blagdan slavimo, Po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"}}});
